import{_ as t,c as l,o as h,j as i,af as n,a as r,t as e}from"./chunks/framework.W5ZyBR1w.js";const u=JSON.parse('{"title":"配置系统服务","description":"本章主要讲述如何将 MSST-Net 客户端核心配置为系统服务。","frontmatter":{"title":"配置系统服务","description":"本章主要讲述如何将 MSST-Net 客户端核心配置为系统服务。"},"headers":[],"relativePath":"connect/install/service.md","filePath":"connect/install/service.md"}'),d={name:"connect/install/service.md"},p={id:"frontmatter-title",tabindex:"-1"};function o(s,a,c,k,b,g){return h(),l("div",null,[i("h1",p,[r(e(s.$frontmatter.title)+" ",1),a[0]||(a[0]=i("a",{class:"header-anchor",href:"#frontmatter-title","aria-label":"Permalink to “{{ $frontmatter.title }}”"},"​",-1))]),i("p",null,e(s.$frontmatter.description),1),a[1]||(a[1]=n('<h2 id="什么是系统服务" tabindex="-1">什么是系统服务 <a class="header-anchor" href="#什么是系统服务" aria-label="Permalink to “什么是系统服务”">​</a></h2><p>系统服务是一种后台运行机制。</p><p>将 <strong>MSST-Net 客户端核心</strong>配置为系统服务后，可以在后台持续运行，并支持开机自动启动。</p><hr><h2 id="为什么推荐配置系统服务" tabindex="-1">为什么推荐配置系统服务 <a class="header-anchor" href="#为什么推荐配置系统服务" aria-label="Permalink to “为什么推荐配置系统服务”">​</a></h2><p>推荐将客户端核心配置为系统服务，主要原因如下：</p><ul><li>开机自动运行</li><li>后台持续运行</li><li>提高运行稳定性</li><li>支持自动恢复</li></ul><p>对于长期接入 MSST-Net 的设备，建议进行配置。</p><hr><h2 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to “Windows”">​</a></h2><p>如果使用客户端安装器，通常可以自动配置系统服务。</p><p>如果需要手动配置，请使用系统服务管理工具完成注册。</p><p>配置完成后，可通过系统服务管理器启动或停止服务。</p><hr><h2 id="linux-systemd" tabindex="-1">Linux（systemd） <a class="header-anchor" href="#linux-systemd" aria-label="Permalink to “Linux（systemd）”">​</a></h2><p>Linux 平台推荐使用 <strong>systemd</strong> 管理客户端核心。</p><h3 id="创建服务文件" tabindex="-1">创建服务文件 <a class="header-anchor" href="#创建服务文件" aria-label="Permalink to “创建服务文件”">​</a></h3><p>服务文件路径：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/etc/systemd/system/msst-net.service</span></span></code></pre></div><h3 id="启用服务" tabindex="-1">启用服务 <a class="header-anchor" href="#启用服务" aria-label="Permalink to “启用服务”">​</a></h3><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> msst-net</span></span></code></pre></div><h3 id="启动服务" tabindex="-1">启动服务 <a class="header-anchor" href="#启动服务" aria-label="Permalink to “启动服务”">​</a></h3><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> msst-net</span></span></code></pre></div><h3 id="查看状态" tabindex="-1">查看状态 <a class="header-anchor" href="#查看状态" aria-label="Permalink to “查看状态”">​</a></h3><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> msst-net</span></span></code></pre></div><h2 id="macos-launchd" tabindex="-1">macOS（launchd） <a class="header-anchor" href="#macos-launchd" aria-label="Permalink to “macOS（launchd）”">​</a></h2><p>macOS 平台推荐使用 launchd 管理客户端核心。</p><p>请将服务配置文件放入：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>~/Library/LaunchAgents/</span></span></code></pre></div><p>或：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/Library/LaunchDaemons/</span></span></code></pre></div><p>配置完成后，使用系统命令加载服务。</p><h2 id="服务管理" tabindex="-1">服务管理 <a class="header-anchor" href="#服务管理" aria-label="Permalink to “服务管理”">​</a></h2><h3 id="启动服务-1" tabindex="-1">启动服务 <a class="header-anchor" href="#启动服务-1" aria-label="Permalink to “启动服务”">​</a></h3><p>启动客户端核心服务。</p><h3 id="停止服务" tabindex="-1">停止服务 <a class="header-anchor" href="#停止服务" aria-label="Permalink to “停止服务”">​</a></h3><p>停止客户端核心服务。</p><h3 id="重启服务" tabindex="-1">重启服务 <a class="header-anchor" href="#重启服务" aria-label="Permalink to “重启服务”">​</a></h3><p>重新启动客户端核心服务。</p><h3 id="查看状态-1" tabindex="-1">查看状态 <a class="header-anchor" href="#查看状态-1" aria-label="Permalink to “查看状态”">​</a></h3><p>查看当前服务运行状态。</p><h3 id="查看日志" tabindex="-1">查看日志 <a class="header-anchor" href="#查看日志" aria-label="Permalink to “查看日志”">​</a></h3><p>建议定期查看运行日志，以便排查问题。</p><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to “注意事项”">​</a></h2><p>客户端控制器通常不建议配置为系统服务。</p><p>如需开机自动打开控制器，请使用系统自带的开机启动功能。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><p>完成系统服务配置后，建议继续：</p><ul><li>完成接入认证</li><li>选择接入方式</li></ul><p>详见：</p><p><a href="/connect/start">《新手教程》</a></p>',51))])}const f=t(d,[["render",o]]);export{u as __pageData,f as default};
